class Inspect(JupyterMixin):
    """A renderable to inspect any Python Object.

    Args:
        obj (Any): An object to inspect.
        title (str, optional): Title to display over inspect result, or None use type. Defaults to None.
        help (bool, optional): Show full help text rather than just first paragraph. Defaults to False.
        methods (bool, optional): Enable inspection of callables. Defaults to False.
        docs (bool, optional): Also render doc strings. Defaults to True.
        private (bool, optional): Show private attributes (beginning with underscore). Defaults to False.
        dunder (bool, optional): Show attributes starting with double underscore. Defaults to False.
        sort (bool, optional): Sort attributes alphabetically, callables at the top, leading and trailing underscores ignored. Defaults to True.
        all (bool, optional): Show all attributes. Defaults to False.
        value (bool, optional): Pretty print value of object. Defaults to True.
    """

    def __init__(
        self,
        obj: Any,
        *,
        title: Optional[TextType] = None,
        help: bool = False,
        methods: bool = False,
        docs: bool = True,
        private: bool = False,
        dunder: bool = False,
        sort: bool = True,
        all: bool = True,
        value: bool = True,
    ) -> None:
        self.highlighter = ReprHighlighter()
        self.obj = obj
        self.title = title or self._make_title(obj)
        if all:
            methods = private = dunder = True
        self.help = help
        self.methods = methods
        self.docs = docs or help
        self.private = private or dunder
        self.dunder = dunder
        self.sort = sort
        self.value = value

    def _make_title(self, obj: Any) -> Text:
        """Make a default title."""
        title_str = (
            str(obj)
            if (isclass(obj) or callable(obj) or ismodule(obj))
            else str(type(obj))
        )
        title_text = self.highlighter(title_str)
        return title_text

    def __rich__(self) -> Panel:
        return Panel.fit(
            Group(*self._render()),
            title=self.title,
            border_style="scope.border",
            padding=(0, 1),
        )

    def _get_signature(self, name: str, obj: Any) -> Optional[Text]:
        """Get a signature for a callable."""
        try:
            _signature = str(signature(obj)) + ":"
        except ValueError:
            _signature = "(...)"
        except TypeError:
            return None

        source_filename: Optional[str] = None
        try:
            source_filename = getfile(obj)
        except (OSError, TypeError):
            # OSError is raised if obj has no source file, e.g. when defined in REPL.
            pass

        callable_name = Text(name, style="inspect.callable")
        if source_filename:
            callable_name.stylize(f"link file://{source_filename}")
        signature_text = self.highlighter(_signature)

        qualname = name or getattr(obj, "__qualname__", name)
        if not isinstance(qualname, str):
            qualname = getattr(obj, "__name__", name)
            if not isinstance(qualname, str):
                qualname = name

        # If obj is a module, there may be classes (which are callable) to display
        if inspect.isclass(obj):
            prefix = "class"
        elif inspect.iscoroutinefunction(obj):
            prefix = "async def"
        else:
            prefix = "def"

        qual_signature = Text.assemble(
            (f"{prefix} ", f"inspect.{prefix.replace(' ', '_')}"),
            (qualname, "inspect.callable"),
            signature_text,
        )

        return qual_signature

    def _render(self) -> Iterable[RenderableType]:
        """Render object."""

        def sort_items(item: Tuple[str, Any]) -> Tuple[bool, str]:
            key, (_error, value) = item
            return (callable(value), key.strip("_").lower())

        def safe_getattr(attr_name: str) -> Tuple[Any, Any]:
            """Get attribute or any exception."""
            try:
                return (None, getattr(obj, attr_name))
            except Exception as error:
                return (error, None)

        obj = self.obj
        keys = dir(obj)
        total_items = len(keys)
        if not self.dunder:
            keys = [key for key in keys if not key.startswith("__")]
        if not self.private:
            keys = [key for key in keys if not key.startswith("_")]
        not_shown_count = total_items - len(keys)
        items = [(key, safe_getattr(key)) for key in keys]
        if self.sort:
            items.sort(key=sort_items)

        items_table = Table.grid(padding=(0, 1), expand=False)
        items_table.add_column(justify="right")
        add_row = items_table.add_row
        highlighter = self.highlighter

        if callable(obj):
            signature = self._get_signature("", obj)
            if signature is not None:
                yield signature
                yield ""

        if self.docs:
            _doc = self._get_formatted_doc(obj)
            if _doc is not None:
                doc_text = Text(_doc, style="inspect.help")
                doc_text = highlighter(doc_text)
                yield doc_text
                yield ""

        if self.value and not (isclass(obj) or callable(obj) or ismodule(obj)):
            yield Panel(
                Pretty(obj, indent_guides=True, max_length=10, max_string=60),
                border_style="inspect.value.border",
            )
            yield ""

        for key, (error, value) in items:
            key_text = Text.assemble(
                (
                    key,
                    "inspect.attr.dunder" if key.startswith("__") else "inspect.attr",
                ),
                (" =", "inspect.equals"),
            )
            if error is not None:
                warning = key_text.copy()
                warning.stylize("inspect.error")
                add_row(warning, highlighter(repr(error)))
                continue

            if callable(value):
                if not self.methods:
                    continue

                _signature_text = self._get_signature(key, value)
                if _signature_text is None:
                    add_row(key_text, Pretty(value, highlighter=highlighter))
                else:
                    if self.docs:
                        docs = self._get_formatted_doc(value)

    Args:
        code (str): Code to highlight.
        line_range(Tuple[int, int], optional): Optional line range to highlight.

    Returns:
        Text: A text instance containing highlighted syntax.
    """

    base_style = self._get_base_style()
    justify: JustifyMethod = (
        "default" if base_style.transparent_background else "left"
    )

    text = Text(
        justify=justify,
        style=base_style,
        tab_size=self.tab_size,
        no_wrap=not self.word_wrap,
    )
    _get_theme_style = self._theme.get_style_for_token

    lexer = self.lexer or self.default_lexer

    if lexer is None:
        text.append(code)
    else:
        if line_range:
            # More complicated path to only stylize a portion of the code
            # This speeds up further operations as there are less spans to process
            line_start, line_end = line_range

            def line_tokenize() -> Iterable[Tuple[Any, str]]:
                """Split tokens to one per line."""
                assert lexer  # required to make MyPy happy - we know lexer is not None at this point

                for token_type, token in lexer.get_tokens(code):
                    while token:
                        line_token, new_line, token = token.partition("\n")
                        yield token_type, line_token + new_line

            def tokens_to_spans() -> Iterable[Tuple[str, Optional[Style]]]:
                """Convert tokens to spans."""
                tokens = iter(line_tokenize())
                line_no = 0
                _line_start = line_start - 1 if line_start else 0

                # Skip over tokens until line start
                while line_no < _line_start:
                    try:
                        _token_type, token = next(tokens)
                    except StopIteration:
                        break
                    yield (token, None)
                    if token.endswith("\n"):
                        line_no += 1
                # Generate spans until line end
                for token_type, token in tokens:
                    yield (token, _get_theme_style(token_type))
                    if token.endswith("\n"):
                        line_no += 1
                        if line_end and line_no >= line_end:
                            break

            text.append_tokens(tokens_to_spans())

        else:
            text.append_tokens(
                (token, _get_theme_style(token_type))
                for token_type, token in lexer.get_tokens(code)
            )
        if self.background_color is not None:
            text.stylize(f"on {self.background_color}")

    if self._stylized_ranges:
        self._apply_stylized_ranges(text)

    return text

def stylize_range(
    self,
    style: StyleType,
    start: SyntaxPosition,
    end: SyntaxPosition,
    style_before: bool = False,
) -> None:
    """
    Adds a custom style on a part of the code, that will be applied to the syntax display when it's rendered.
    Line numbers are 1-based, while column indexes are 0-based.

    Args:
        style (StyleType): The style to apply.
        start (Tuple[int, int]): The start of the range, in the form `[line number, column index]`.
        end (Tuple[int, int]): The end of the range, in the form `[line number, column index]`.
        style_before (bool): Apply the style before any existing styles.
    """
    self._stylized_ranges.append(
        _SyntaxHighlightRange(style, start, end, style_before)
    )

def _get_line_numbers_color(self, blend: float = 0.3) -> Color:
    background_style = self._theme.get_background_style() + self.background_style
    background_color = background_style.bgcolor
    if background_color is None or background_color.is_system_defined:
        return Color.default()
    foreground_color = self._get_token_color(Token.Text)
    if foreground_color is None or foreground_color.is_system_defined:
        return foreground_color or Color.default()
    new_color = blend_rgb(
        background_color.get_truecolor(),
        foreground_color.get_truecolor(),
        cross_fade=blend,
    )
    return Color.from_triplet(new_color)

@property
def _numbers_column_width(self) -> int:
    """Get the number of characters used to render the numbers column."""
    column_width = 0
    if self.line_numbers:
        column_width = (
            len(str(self.start_line + self.code.count("\n")))
            + NUMBERS_COLUMN_DEFAULT_PADDING
        )
    return column_width

def _get_number_styles(self, console: Console) -> Tuple[Style, Style, Style]:
    """Get background, number, and highlight styles for line numbers."""
    background_style = self._get_base_style()
    if background_style.transparent_background:
        return Style.null(), Style(dim=True), Style.null()
    if console.color_system in ("256", "truecolor"):
        number_style = Style.chain(
            background_style,
            self._theme.get_style_for_token(Token.Text),
            Style(color=self._get_line_numbers_color()),
            self.background_style,
        )
        highlight_number_style = Style.chain(
            background_style,
            self._theme.get_style_for_token(Token.Text),
            Style(bold=True, color=self._get_line_numbers_color(0.9)),
            self.background_style,
        )
    else:
        number_style = background_style + Style(dim=True)
        highlight_number_style = background_style + Style(dim=False)
    return background_style, number_style, highlight_number_style

def __rich_measure__(
    self, console: "Console", options: "ConsoleOptions"
) -> "Measurement":
    _, right, _, left = self.padding
    padding = left + right
    if self.code_width is not None:
        width = self.code_width + self._numbers_column_width + padding + 1
        return Measurement(self._numbers_column_width, width)
    lines = self.code.splitlines()
    width = (
        self._numbers_column_width
        + padding
        + (max(cell_len(line) for line in lines) if lines else 0)
    )
    if self.line_numbers:
        width += 1
    return Measurement(self._numbers_column_width, width)

def __rich_console__(
    self, console: Console, options: ConsoleOptions
) -> RenderResult:
    segments = Segments(self._get_syntax(console, options))
    if any(self.padding):
        yield Padding(segments, style=self._get_base_style(), pad=self.padding)
    else:
        yield segments

def _get_syntax(
    self,
    console: Console,
    options: ConsoleOptions,
) -> Iterable[Segment]:
    """
    Get the Segments for the Syntax object, excluding any vertical/horizontal padding
    """
    transparent_background = self._get_base_style().transparent_background
    _pad_top, pad_right, _pad_bottom, pad_left = self.padding
    horizontal_padding = pad_left + pad_right
    code_width = (
        (
            (options.max_width - self._numbers_column_width - 1)
            if self.line_numbers
            else options.max_width
        )
        - horizontal_padding
        if self.code_width is None
        else self.code_width
    )
    code_width = max(0, code_width)

    ends_on_nl, processed_code = self._process_code(self.code)
